import Foundation
import Security
import UIKit

// Swift twin of android/.../core/Stores.kt. Keys, defaults, clamps and the
// PairedHost JSON shape are identical to Android.

// MARK: - Identity

/// The phone's LANLink identity (certificate + private key). The blob is
/// generated by the native core (the TLS stack needs the raw key) and kept in
/// the Keychain: this device only, after first unlock, never synced.
final class IdentityStore {
    static let defaultService = "io.lanlink.identity"
    private static let account = "identity"

    private let service: String
    private let lock = NSLock()
    private var cached: Data?

    init(service: String = IdentityStore.defaultService) {
        self.service = service
    }

    var baseQuery: [String: Any] {
        [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: IdentityStore.account,
            kSecAttrSynchronizable as String: false,
        ]
    }

    /// Load the identity, creating it on first use.
    func get(deviceLabel: String) throws -> Data {
        lock.lock()
        defer { lock.unlock() }
        if let cached { return cached }

        var read = baseQuery
        read[kSecReturnData as String] = true
        read[kSecMatchLimit as String] = kSecMatchLimitOne
        var item: CFTypeRef?
        let status = SecItemCopyMatching(read as CFDictionary, &item)
        switch status {
        case errSecSuccess:
            if let data = item as? Data, !data.isEmpty {
                cached = data
                return data
            }
            // Read succeeded but the bytes are empty or not Data: corrupt.
            // Replace it below.
        case errSecItemNotFound:
            break
        default:
            // Transient or unknown failure (e.g. device locked): never
            // delete or regenerate, that would unpair every PC.
            throw LANLinkError(message: "The identity could not be read (Keychain error \(status)).")
        }

        let id = try Bridge.generateIdentity(label: deviceLabel)
        let add = addAttributes(for: id)
        var addStatus = SecItemAdd(add as CFDictionary, nil)
        if addStatus == errSecDuplicateItem {
            SecItemDelete(baseQuery as CFDictionary)
            addStatus = SecItemAdd(add as CFDictionary, nil)
        }
        guard addStatus == errSecSuccess else {
            throw LANLinkError(message: "The identity could not be saved (Keychain error \(addStatus)).")
        }
        cached = id
        return id
    }

    /// Attributes used to store the identity blob.
    func addAttributes(for id: Data) -> [String: Any] {
        var add = baseQuery
        add[kSecValueData as String] = id
        add[kSecAttrAccessible as String] = kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly
        return add
    }

    func fingerprint(deviceLabel: String) throws -> String {
        try Bridge.identityFingerprint(get(deviceLabel: deviceLabel))
    }

    /// Forget the identity. Every PC will treat this phone as new.
    func clear() {
        lock.lock()
        defer { lock.unlock() }
        cached = nil
        SecItemDelete(baseQuery as CFDictionary)
    }
}

// MARK: - Paired hosts

/// A PC this phone has paired with.
struct PairedHost: Codable, Equatable {
    var fingerprint: String
    var name: String
    var addresses: [String]
    var port: Int
    var pairedAt: Int64
    var lastConnected: Int64

    /// First 16 hex digits; matches the mDNS `id` of the host.
    var shortId: String { String(fingerprint.prefix(16)) }

    private enum CodingKeys: String, CodingKey {
        case fingerprint = "fp"
        case name
        case addresses = "addrs"
        case port
        case pairedAt
        case lastConnected = "last"
    }

    init(
        fingerprint: String, name: String, addresses: [String], port: Int,
        pairedAt: Int64, lastConnected: Int64
    ) {
        self.fingerprint = fingerprint
        self.name = name
        self.addresses = addresses
        self.port = port
        self.pairedAt = pairedAt
        self.lastConnected = lastConnected
    }

    /// Same leniency as Kotlin's `fromJson`: only `fp` is required.
    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        fingerprint = try c.decode(String.self, forKey: .fingerprint)
        name = (try? c.decode(String.self, forKey: .name)) ?? "PC"
        addresses = (try? c.decode([String].self, forKey: .addresses)) ?? []
        port = (try? c.decode(Int.self, forKey: .port)) ?? 47990
        pairedAt = (try? c.decode(Int64.self, forKey: .pairedAt)) ?? 0
        lastConnected = (try? c.decode(Int64.self, forKey: .lastConnected)) ?? 0
    }

    static func listToJson(_ hosts: [PairedHost]) -> String {
        guard let data = try? JSONEncoder().encode(hosts) else { return "[]" }
        return String(decoding: data, as: UTF8.self)
    }

    static func listFromJson(_ s: String?) -> [PairedHost] {
        guard let data = (s ?? "[]").data(using: .utf8),
              let list = try? JSONDecoder().decode([PairedHost].self, from: data)
        else { return [] }
        return list
    }
}

/// Paired PCs. Fingerprints are public, but the list is kept app-private.
final class HostRepository {
    private let defaults: UserDefaults
    private let lock = NSRecursiveLock()
    private static let listKey = "list"

    init(defaults: UserDefaults = HostRepository.standardDefaults) {
        self.defaults = defaults
    }

    static var standardDefaults: UserDefaults {
        UserDefaults(suiteName: "hosts") ?? .standard
    }

    func all() -> [PairedHost] {
        lock.lock()
        defer { lock.unlock() }
        let list = PairedHost.listFromJson(defaults.string(forKey: HostRepository.listKey))
        // Stable sort by lastConnected, newest first.
        return list.enumerated()
            .sorted { l, r in
                l.element.lastConnected != r.element.lastConnected
                    ? l.element.lastConnected > r.element.lastConnected
                    : l.offset < r.offset
            }
            .map { $0.element }
    }

    func get(_ fp: String) -> PairedHost? {
        all().first { $0.fingerprint == fp }
    }

    func put(_ h: PairedHost) {
        lock.lock()
        defer { lock.unlock() }
        let list = all().filter { $0.fingerprint != h.fingerprint } + [h]
        defaults.set(PairedHost.listToJson(list), forKey: HostRepository.listKey)
    }

    func remove(_ fp: String) {
        lock.lock()
        defer { lock.unlock() }
        defaults.set(
            PairedHost.listToJson(all().filter { $0.fingerprint != fp }),
            forKey: HostRepository.listKey)
    }

    func clear() {
        lock.lock()
        defer { lock.unlock() }
        defaults.removeObject(forKey: HostRepository.listKey)
    }

    func touch(fp: String, address: String) {
        lock.lock()
        defer { lock.unlock() }
        guard var h = get(fp) else { return }
        var addrs: [String] = []
        for a in [address] + h.addresses where !addrs.contains(a) { addrs.append(a) }
        h.addresses = Array(addrs.prefix(6))
        h.lastConnected = Int64(Date().timeIntervalSince1970 * 1000)
        put(h)
    }
}

// MARK: - Settings

enum Quality: Int {
    case smooth = 0, balanced = 1, sharp = 2, custom = 3

    /// Stored name, as on Android (`Quality.name`).
    var storedName: String {
        switch self {
        case .smooth: return "SMOOTH"
        case .balanced: return "BALANCED"
        case .sharp: return "SHARP"
        case .custom: return "CUSTOM"
        }
    }

    init?(storedName: String) {
        switch storedName {
        case "SMOOTH": self = .smooth
        case "BALANCED": self = .balanced
        case "SHARP": self = .sharp
        case "CUSTOM": self = .custom
        default: return nil
        }
    }

    var wire: Int { rawValue }

    var label: String {
        switch self {
        case .smooth: return "Smooth"
        case .balanced: return "Balanced"
        case .sharp: return "Sharp"
        case .custom: return "Custom"
        }
    }
}

/// User preferences. Plain values, no secrets.
final class Settings {
    private static let keys = [
        "onboarded", "quality", "pointer", "sens", "accel", "fps", "kbps", "maxw", "maxkbps",
        "fill", "compactKeyboard", "keyHeight", "allowShots", "controlsLeft", "landscape",
        "startzoom", "stats", "awake", "viewonly", "devname",
    ]

    private let p: UserDefaults

    init(defaults: UserDefaults = Settings.standardDefaults) {
        self.p = defaults
    }

    static var standardDefaults: UserDefaults {
        UserDefaults(suiteName: "settings") ?? .standard
    }

    private func bool(_ key: String, _ def: Bool) -> Bool {
        (p.object(forKey: key) as? NSNumber)?.boolValue ?? def
    }

    private func float(_ key: String, _ def: Float) -> Float {
        (p.object(forKey: key) as? NSNumber)?.floatValue ?? def
    }

    private func int(_ key: String, _ def: Int) -> Int {
        (p.object(forKey: key) as? NSNumber)?.intValue ?? def
    }

    var onboarded: Bool {
        get { bool("onboarded", false) }
        set { p.set(newValue, forKey: "onboarded") }
    }

    var quality: Quality {
        get { Quality(storedName: p.string(forKey: "quality") ?? "BALANCED") ?? .balanced }
        set { p.set(newValue.storedName, forKey: "quality") }
    }

    var pointerMode: PointerMode {
        get { PointerMode(rawValue: p.string(forKey: "pointer") ?? "TRACKPAD") ?? .trackpad }
        set { p.set(newValue.rawValue, forKey: "pointer") }
    }

    var sensitivity: Float {
        get { float("sens", 1.0) }
        set { p.set(newValue, forKey: "sens") }
    }

    var acceleration: Float {
        get { float("accel", 0.5) }
        set { p.set(newValue, forKey: "accel") }
    }

    /// Custom-mode values; 0 = automatic.
    var customFps: Int {
        get { int("fps", 0) }
        set { p.set(newValue, forKey: "fps") }
    }

    var customKbps: Int {
        get { int("kbps", 0) }
        set { p.set(newValue, forKey: "kbps") }
    }

    var customMaxWidth: Int {
        get { int("maxw", 0) }
        set { p.set(newValue, forKey: "maxw") }
    }

    var maxKbps: Int {
        get { int("maxkbps", 0) }
        set { p.set(newValue, forKey: "maxkbps") }
    }

    var fillScreen: Bool {
        get { bool("fill", false) }
        set { p.set(newValue, forKey: "fill") }
    }

    /// Use LANLink's compact keyboard instead of the phone's own.
    var compactKeyboard: Bool {
        get { bool("compactKeyboard", true) }
        set { p.set(newValue, forKey: "compactKeyboard") }
    }

    /// Key height of the compact keyboard in points.
    var keyHeight: Float {
        get { min(max(float("keyHeight", 36), 28), 48) }
        set { p.set(min(max(newValue, 28), 48), forKey: "keyHeight") }
    }

    /// Allow screenshots and screen recording while the PC is shown. Off by
    /// default: the PC screen often holds passwords and one-time codes.
    var allowScreenshots: Bool {
        get { bool("allowShots", false) }
        set { p.set(newValue, forKey: "allowShots") }
    }

    /// Session controls on the left edge instead of the right.
    var controlsLeft: Bool {
        get { bool("controlsLeft", false) }
        set { p.set(newValue, forKey: "controlsLeft") }
    }

    /// Turn the phone sideways while controlling (the PC is landscape).
    var landscape: Bool {
        get { bool("landscape", true) }
        set { p.set(newValue, forKey: "landscape") }
    }

    /// Zoom the view starts at in trackpad mode (1 = whole desktop).
    var startZoom: Float {
        get { float("startzoom", 2) }
        set { p.set(min(max(newValue, 1), 4), forKey: "startzoom") }
    }

    var showStats: Bool {
        get { bool("stats", false) }
        set { p.set(newValue, forKey: "stats") }
    }

    var keepScreenOn: Bool {
        get { bool("awake", true) }
        set { p.set(newValue, forKey: "awake") }
    }

    var viewOnly: Bool {
        get { bool("viewonly", false) }
        set { p.set(newValue, forKey: "viewonly") }
    }

    var deviceName: String {
        get { p.string(forKey: "devname") ?? Settings.defaultDeviceName() }
        set { p.set(String(newValue.prefix(48)), forKey: "devname") }
    }

    func clear() {
        for key in Settings.keys { p.removeObject(forKey: key) }
    }

    /// The user's device name, or the model name when iOS only reports the
    /// generic "iPhone".
    static func defaultDeviceName() -> String {
        let device = UIDevice.current
        let name = device.name
        let chosen = (name.isEmpty || name == "iPhone") ? device.model : name
        return DisplayText.name(s: chosen)
    }
}
